import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= x <= 255, 0 <= k <= 7).

    Bits shifted out of the high end wrap around to the low end.
    The result is always in the range 0 to 255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xA5, 0xFF):
        assert rotl8(x, 0) == x


def test_rotl8_known_values() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0x80, 1) == 0x01
    assert rotl8(0b10010110, 3) == 0b10110100
    assert rotl8(0x01, 7) == 0x80
    assert rotl8(0x01, 4) == 0x10


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(0xFF, k) == 0xFF


@pytest.mark.parametrize("k", range(8))
def test_rotl8_matches_string_rotation(k: int) -> None:
    for x in range(256):
        bits = format(x, "08b")
        expected = int(bits[k:] + bits[:k], 2)
        assert rotl8(x, k) == expected


def test_rotl8_result_in_range_and_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            r = rotl8(x, k)
            assert 0 <= r <= 255
            assert bin(r).count("1") == bin(x).count("1")


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x
